import * as React from "react";

import { Calendar } from "@/registry/erbium/ui/calendar";
import type { DateRange } from "@/registry/erbium/ui/calendar";
import { addDays } from "@/registry/erbium/lib/date";

export const CalendarRange = () => {
  const [dateRange, setDateRange] = React.useState<DateRange | undefined>(() => {
    const from = new Date(new Date().getFullYear(), 0, 12);

    return { from, to: addDays(from, 30) };
  });

  return (
    <Calendar
      mode="range"
      defaultMonth={dateRange?.from}
      selected={dateRange}
      onSelect={setDateRange}
      numberOfMonths={2}
    />
  );
};

import { CalendarRange } from "../examples/calendar-range";

const Example = () => <CalendarRange />;

export default Example;
